// Generates the framework packages from the component contract (packages/core/custom-elements.json).
// NEVER edit packages/*/generated by hand: change the component (its JSDoc / properties) or this generator.
// Run by each framework package's build, or for all: `pnpm generate`.
//
//   node scripts/gen-frameworks.mjs [react|preact|solid|vue|angular|svelte|examples ...]   (none = all)
import { mkdirSync, readFileSync, rmSync, writeFileSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { camel, pascal, readElements, root } from './contract.mjs'

const BANNER = '// GENERATED by scripts/gen-frameworks.mjs from packages/core/custom-elements.json. Do not edit.\n'

// ---------------------------------------------------------------------------------------------- the contract
/** Every element: tag, class, the module to import it from, its define function, inputs, events and names */
const elements = readElements()
const byEntry = Map.groupBy ? Map.groupBy(elements, (e) => e.entry) : elements.reduce((m, e) => m.set(e.entry, [...(m.get(e.entry) ?? []), e]), new Map())

const write = (file, text) => {
  mkdirSync(dirname(file), { recursive: true })
  writeFileSync(file, text)
}
const fresh = (pkg) => {
  const dir = join(root, 'packages', pkg, 'generated')
  rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  return dir
}
/** `import type { SubSelect } from '@sub/core/select'` for the element types an output needs */
const typeImports = (list) =>
  [...new Map(list.filter((e) => e.exported).map((e) => [e.className, e])).values()].map((e) => `import type { ${e.className} } from '@sub/core/${e.entry}'`).join('\n')
const elType = (e) => (e.exported ? e.className : 'HTMLElement')
/** Typed properties of an element: the component's own declarations, picked by name */
const propsType = (e) => (e.exported && e.props.length ? `Partial<Pick<${e.className}, ${e.props.map((p) => `'${p.name}'`).join(' | ')}>>` : '{}')
const registerAll = (list) =>
  [...byEntry.keys()]
    .filter((entry) => list.some((e) => e.entry === entry))
    .map((entry) => byEntry.get(entry)[0])
    .filter((e) => e.define)

// ---------------------------------------------------------------------------------------------- React
function react() {
  const dir = fresh('react')
  const index = []
  for (const e of elements) {
    const file = e.tag.replace(/^sub-/, '')
    write(
      join(dir, `${file}.ts`),
      `${BANNER}import * as React from 'react'
import { createComponent, type EventName } from '@lit/react'
import { ${e.exported ? `${e.className} as Element, ` : ''}${e.define} } from '@sub/core/${e.entry}'

// registered on import (only in the browser: safe to import during SSR)
if (typeof customElements !== 'undefined') ${e.define}()

/** \`<${e.tag}>\` as a React component: properties as props, events as ${e.events.length ? e.events.map((v) => `\`${v.handler}\``).join(', ') : 'none'}, \`ref\` = the element */
export const ${e.component} = createComponent({
  tagName: '${e.tag}',
  elementClass: ${e.exported ? 'Element' : '(typeof HTMLElement !== "undefined" ? HTMLElement : class {}) as typeof HTMLElement'},
  react: React,
  displayName: '${e.component}',
  events: {
${e.events.map((v) => `    ${v.handler}: '${v.name}' as EventName<${v.type}>,`).join('\n')}
  },
})
`,
    )
    index.push(`export { ${e.component} } from './${file}'`)
  }
  write(join(dir, 'index.ts'), `${BANNER}${index.join('\n')}\n`)
}

// ---------------------------------------------------------------------------------------------- Vue
function vue() {
  const dir = fresh('vue')
  const index = []
  for (const e of elements) {
    const file = e.tag.replace(/^sub-/, '')
    const emits = e.events.map((v) => `    '${v.name}': (_event: ${v.type}) => true,`)
    // the element type under an alias: the component itself takes the class name
    const T = (name) => (e.exported ? `Element['${name}']` : 'unknown')
    if (e.model) emits.push(`    'update:modelValue': (_value: ${T(e.model)}) => true,`)
    write(
      join(dir, `${file}.ts`),
      `${BANNER}import { defineComponent, h, ref, type PropType } from 'vue'
import { ${e.define}${e.exported ? `, type ${e.className} as Element` : ''} } from '@sub/core/${e.entry}'

if (typeof customElements !== 'undefined') ${e.define}()

const PROPS = [${e.props.map((p) => `'${p.name}'`).join(', ')}] as const

/** \`<${e.tag}>\` as a Vue component: properties as props${e.model ? `, \`v-model\` on \`${e.model}\`` : ''}, events as emits; \`ref.el\` = the element */
export const ${e.component} = defineComponent({
  name: '${e.component}',
  inheritAttrs: false,
  props: {
${e.props.map((p) => `    ${p.name}: { type: ${p.boolean ? "Boolean" : p.number ? "Number" : "null"} as unknown as PropType<${T(p.name)}>, default: undefined },`).join('\n')}
${e.model ? `    modelValue: { type: null as unknown as PropType<${T(e.model)}>, default: undefined },` : ''}
  },
  emits: {
${emits.join('\n')}
  },
  setup(props, { attrs, slots, emit, expose }) {
    const el = ref<${e.exported ? 'Element' : 'HTMLElement'}>()
    expose({ el })
    return () => {
      const data: Record<string, unknown> = { ...attrs, ref: el }
      for (const name of PROPS) if (props[name] !== undefined) data[name] = props[name]
${e.model ? `      if (props.modelValue !== undefined) data['${e.model}'] = props.modelValue\n` : ''}${e.events
        .map((v) => {
          const sync = e.model && (v.name === 'change' || v.name === 'input') ? ` emit('update:modelValue', (event.currentTarget as any).${e.model});` : ''
          return `      data['on${pascal(v.name)}'] = (event: ${v.type}) => {${sync} emit('${v.name}', event) }`
        })
        .join('\n')}
${e.model && !e.events.some((v) => v.name === 'input') ? `      data.onInput = (event: Event) => emit('update:modelValue', (event.currentTarget as any).${e.model})\n` : ''}      return h('${e.tag}', data, slots.default?.())
    }
  },
})
`,
    )
    index.push(`export { ${e.component} } from './${file}'`)
  }
  index.push(
    `\n/** Every component, for \`app.use(SubPlugin)\` (prefer importing the ones you use: smaller bundles) */`,
    `import type { App } from 'vue'`,
    `import * as all from './all'`,
    `export const SubPlugin = { install(app: App) { for (const [name, component] of Object.entries(all)) app.component(name, component) } }`,
  )
  write(join(dir, 'all.ts'), `${BANNER}${elements.map((e) => `export { ${e.component} } from './${e.tag.replace(/^sub-/, '')}'`).join('\n')}\n`)
  write(join(dir, 'index.ts'), `${BANNER}${index.join('\n')}\n`)
}

// ---------------------------------------------------------------------------------------------- Angular
function angular() {
  const dir = fresh('angular')
  const index = []
  const names = []
  for (const e of elements) {
    const file = e.tag.replace(/^sub-/, '')
    const directive = e.directive
    names.push(directive)
    const inputs = e.props.map(
      // a static attribute reaches an input as a string: `<sub-switch checked>` must be true, `max="5"` a number
      (p) => `  /** ${p.name}${p.attribute ? ` (attribute \`${p.attribute}\`)` : ''} */
  @Input(${p.boolean ? '{ transform: booleanAttribute }' : p.number ? '{ transform: numberAttribute }' : ''}) set ${p.name}(value: ${e.exported ? `${e.className}['${p.name}']` : 'unknown'}) {
    ;(this.el as any).${p.name} = value
  }`,
    )
    const outputs = e.events.map((v) => `  @Output('${v.name}') readonly ${camel(v.name)} = new EventEmitter<${v.type}>()`)
    let accessor = ''
    if (e.model) {
      const acc = `${e.component}ValueAccessor`
      names.push(acc)
      accessor = `
/** Angular forms (\`formControl\`, \`formControlName\`, \`ngModel\`) on \`<${e.tag}>\`: reads and writes \`${e.model}\` */
@Directive({
  selector: '${e.tag}[formControlName],${e.tag}[formControl],${e.tag}[ngModel]',
  standalone: true,
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => ${acc}), multi: true }],
  host: { '(change)': 'changed()', '(input)': 'changed()', '(focusout)': 'touched()' },
})
export class ${acc} implements ControlValueAccessor {
  private readonly el = inject<ElementRef<${elType(e)}>>(ElementRef).nativeElement
  private onChange: (value: unknown) => void = () => {}
  private onTouched: () => void = () => {}
  writeValue(value: unknown): void {
    ;(this.el as any).${e.model} = value ?? ${e.model === 'checked' ? 'false' : "''"}
  }
  registerOnChange(fn: (value: unknown) => void): void {
    this.onChange = fn
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn
  }
  setDisabledState(disabled: boolean): void {
    ;(this.el as any).disabled = disabled
  }
  changed(): void {
    this.onChange((this.el as any).${e.model})
  }
  touched(): void {
    this.onTouched()
  }
}
`
    }
    write(
      join(dir, `${file}.ts`),
      `${BANNER}import { Directive, ElementRef, EventEmitter, Input, Output, booleanAttribute, forwardRef, inject, numberAttribute } from '@angular/core'
import { NG_VALUE_ACCESSOR, type ControlValueAccessor } from '@angular/forms'
import { ${e.define}${e.exported ? `, type ${e.className}` : ''} } from '@sub/core/${e.entry}'

if (typeof customElements !== 'undefined') ${e.define}()

/** \`<${e.tag}>\`: typed property inputs and event outputs (\`(${e.events[0]?.name ?? 'event'})\` gives the typed event) */
@Directive({ selector: '${e.tag}', standalone: true, exportAs: '${camel(e.tag)}' })
export class ${directive} {
  /** The element itself, for its methods */
  readonly el = inject<ElementRef<${elType(e)}>>(ElementRef).nativeElement
${inputs.join('\n')}
${outputs.join('\n')}
  constructor() {
${e.events.map((v) => `    this.el.addEventListener('${v.name}', (event) => this.${camel(v.name)}.emit(event as ${v.type}))`).join('\n')}
  }
}
${accessor}`,
    )
    index.push(`export * from './${file}'`)
  }
  index.push(
    `\nimport { ${names.join(', ')} } from './all'`,
    `/** Every directive and value accessor: \`imports: [SUB]\` in a standalone component */`,
    `export const SUB = [${names.join(', ')}] as const`,
  )
  write(join(dir, 'all.ts'), `${BANNER}${elements.map((e) => `export * from './${e.tag.replace(/^sub-/, '')}'`).join('\n')}\n`)
  write(join(dir, 'index.ts'), `${BANNER}${index.join('\n')}\n`)
}

// ---------------------------------------------------------------------------------------------- JSX / Svelte types
/** The component's own property names win over same-named HTML attributes (`size`, `type`, `value`...) */
const ownKeys = (e) => (e.props.length ? e.props.map((p) => `'${p.name}'`).join(' | ') : 'never')
/** Types of one element for a JSX-like dialect */
const intrinsic = (e, base, eventKey) =>
  `    '${e.tag}': Omit<${base(elType(e))}, ${ownKeys(e)}> & ${propsType(e)} & {
${e.events.map((v) => `      '${eventKey(v.name)}'?: (event: ${v.type}) => void`).join('\n')}
    }`

function preact() {
  const dir = fresh('preact')
  write(
    join(dir, 'elements.ts'),
    `${BANNER}import type { JSX } from 'preact'
${typeImports(elements)}

declare module 'preact' {
  namespace JSX {
    interface IntrinsicElements {
${elements.map((e) => intrinsic(e, (t) => `JSX.HTMLAttributes<${t}>`, (n) => `on${n}`)).join('\n')}
    }
  }
}
`,
  )
  writeRegister(dir)
}

function solid() {
  const dir = fresh('solid')
  // Solid types `on:<name>` itself from JSX.CustomEvents (an own declaration would clash with its `on:*` signature):
  // one entry per event name, the union of what the components that fire it send
  const custom = new Map()
  for (const e of elements) for (const v of e.events) if (v.name.startsWith('sub-')) custom.set(v.name, new Set([...(custom.get(v.name) ?? []), v.type]))
  write(
    join(dir, 'elements.ts'),
    `${BANNER}import type { JSX } from 'solid-js'
${typeImports(elements)}

/** \`prop:name\` forces a property (objects, arrays) */
type Props<T> = { [K in keyof T as \`prop:\${string & K}\`]?: T[K] }

declare module 'solid-js' {
  namespace JSX {
    interface IntrinsicElements {
${elements.map((e) => `    '${e.tag}': Omit<JSX.HTMLAttributes<${elType(e)}>, ${ownKeys(e)}> & ${propsType(e)} & Props<${propsType(e)}>`).join('\n')}
    }
    /** \`on:sub-select\` and the other SUB events, typed */
    interface CustomEvents {
${[...custom].map(([name, types]) => `      '${name}': ${[...types].join(' | ')}`).join('\n')}
    }
  }
}
`,
  )
  writeRegister(dir)
}

function svelte() {
  const dir = fresh('svelte')
  write(
    join(dir, 'elements.ts'),
    `${BANNER}import type { HTMLAttributes } from 'svelte/elements'
${typeImports(elements)}

declare module 'svelte/elements' {
  interface SvelteHTMLElements {
${elements.map((e) => intrinsic(e, (t) => `HTMLAttributes<${t}>`, (n) => `on${n}`)).join('\n')}
  }
}
`,
  )
  writeRegister(dir)
}

/** `register.ts`: one function per element (and `registerAll`) for the type-only packages */
function writeRegister(dir) {
  const list = registerAll(elements)
  write(
    join(dir, 'register.ts'),
    `${BANNER}${list.map((e) => `import { ${e.define} } from '@sub/core/${e.entry}'`).join('\n')}

export { ${list.map((e) => e.define).join(', ')} }

/** Registers every component (or import the define function of each one you use: smaller bundles) */
export function registerAll(): void {
  if (typeof customElements === 'undefined') return
${list.map((e) => `  ${e.define}()`).join('\n')}
}
`,
  )
}

// ---------------------------------------------------------------------------------------------- examples
/** What the example galleries need at run time: attribute -> property, kinds, events, the model property */
function examples() {
  const meta = Object.fromEntries(
    elements.map((e) => [
      e.tag,
      {
        component: e.component,
        attributes: Object.fromEntries(e.props.filter((p) => p.attribute).map((p) => [p.attribute, [p.name, p.boolean ? 'boolean' : p.number ? 'number' : 'string']])),
        events: e.events.map((v) => v.name),
        model: e.model,
      },
    ]),
  )
  write(join(root, 'examples/shared/generated/elements.ts'), `${BANNER}export const ELEMENTS: Record<string, { component: string; attributes: Record<string, [string, 'boolean' | 'number' | 'string']>; events: string[]; model: string | null }> = ${JSON.stringify(meta, null, 1)}\n`)

  // Angular cannot render markup it did not compile: its gallery template is generated from the demos
  const demosDir = join(root, 'playground/src/demos')
  const cards = []
  for (const file of readdirSync(demosDir).filter((f) => f.endsWith('.ts')).sort()) {
    const source = readFileSync(join(demosDir, file), 'utf8')
    const id = file.replace(/\.ts$/, '')
    const title = JSON.parse(source.match(/^\s*title:\s*("(?:[^"\\]|\\.)*")/m)[1])
    const html = source.match(/^\s*html:\s*`([\s\S]*?)`,\s*$/m)?.[1]
    if (html === undefined || html.includes('${')) continue
    const template = html
      .trim()
      .replace(/[{}@]/g, (c) => (c === '@' ? '&#64;' : `{{ '${c}' }}`))
      .replace(/<(sub-[a-z-]+)(\s|>)/g, (all, tag, after) => {
        const events = meta[tag]?.events ?? []
        return `<${tag} ${events.map((n) => `(${n})="log('${id}', $event)"`).join(' ')}${after}`
      })
    cards.push(`<article class="card" data-card="${id}">
  <h2>${title}</h2>
  <div class="preview" data-preview="${id}">
${template}
  </div>
  <output class="log" [attr.data-log]="'${id}'">{{ logs['${id}'] ?? 'No event yet' }}</output>
</article>`)
  }
  write(join(root, 'examples/angular/src/generated/gallery.html'), `<!-- GENERATED by scripts/gen-frameworks.mjs from playground/src/demos. Do not edit. -->\n${cards.join('\n')}\n`)
}

const all = { react, vue, angular, preact, solid, svelte, examples }
const wanted = process.argv.slice(2)
for (const name of wanted.length ? wanted : Object.keys(all)) {
  if (!all[name]) throw new Error(`Unknown target "${name}". One of: ${Object.keys(all).join(', ')}`)
  all[name]()
}
console.log(`${elements.length} elements -> ${wanted.length ? wanted.join(', ') : Object.keys(all).join(', ')}`)
